import{_ as t,c as o,o as a,ae as r}from"./chunks/framework.CliRSA9F.js";const s="/images/signup.webp",i="/images/select_your_podcast.webp",n="/images/onboarding_distribution.webp",d="/images/onboarding_visibility.webp",l="/images/onboarding_keywords.webp",p="/images/add_podcast_sidebar.webp",w=JSON.parse('{"title":"Getting Started with Podseo","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/first-steps.md","filePath":"getting-started/first-steps.md"}'),c={name:"getting-started/first-steps.md"};function u(h,e,g,m,y,f){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="getting-started-with-podseo" tabindex="-1">Getting Started with Podseo <a class="header-anchor" href="#getting-started-with-podseo" aria-label="Permalink to &quot;Getting Started with Podseo&quot;">​</a></h1><p>Welcome to Podseo, your go-to platform for podcast competitive intelligence and SEO insights! This guide will help you quickly set up and start analyzing your podcast&#39;s performance.</p><hr><h3 id="_1-create-an-account" tabindex="-1">1. <strong>Create an Account</strong> <a class="header-anchor" href="#_1-create-an-account" aria-label="Permalink to &quot;1. **Create an Account**&quot;">​</a></h3><p>To access Podseo features:</p><ul><li><p>Visit our <a href="https://podseo.com/accounts/signup/" target="_blank" rel="noreferrer">signup page</a>.</p></li><li><p>Enter your details and verify your email.</p></li></ul><p><img src="'+s+'" alt="Signup Screenshot" width="250px" style="display:block;margin:0 auto;"></p><p>Already have an account? <a href="https://podseo.com/accounts/login/" target="_blank" rel="noreferrer">Log in</a> to get started.</p><hr><h3 id="_2-add-your-podcast" tabindex="-1">2. <strong>Add Your Podcast</strong> <a class="header-anchor" href="#_2-add-your-podcast" aria-label="Permalink to &quot;2. **Add Your Podcast**&quot;">​</a></h3><p>After logging in, you&#39;ll see the &quot;Select Your Podcast&quot; screen. Click <strong>Find Your Podcast</strong> to search for your show on Apple Podcasts.</p><p><img src="'+i+'" alt="Select Your Podcast" width="500px" style="display:block;margin:0 auto;"></p><p>Search for your podcast using its name or author details, then select it from the results.</p><h3 id="_3-complete-the-onboarding-wizard" tabindex="-1">3. <strong>Complete the Onboarding Wizard</strong> <a class="header-anchor" href="#_3-complete-the-onboarding-wizard" aria-label="Permalink to &quot;3. **Complete the Onboarding Wizard**&quot;">​</a></h3><p>Once you select your podcast, PodSEO walks you through a guided setup with four steps:</p><p><strong>Distribution</strong> — PodSEO connects your RSS feed and checks your presence across Apple Podcasts, Spotify, Amazon Music, and YouTube Music. You&#39;ll see which platforms found your show and can continue while checks finish in the background.</p><p><img src="'+n+'" alt="Onboarding Distribution" width="500px" style="display:block;margin:0 auto;"></p><p><strong>Visibility</strong> — Your initial Visibility Score is calculated, giving you a baseline of how discoverable your podcast is across platforms.</p><p><img src="'+d+'" alt="Onboarding Visibility" width="500px" style="display:block;margin:0 auto;"></p><p><strong>Keywords</strong> — PodSEO suggests initial keywords based on your podcast&#39;s content. You can review and adjust these to start building your keyword strategy.</p><p><img src="'+l+'" alt="Onboarding Keywords" width="500px" style="display:block;margin:0 auto;"></p><p><strong>Next Steps</strong> — A summary of recommended actions to get the most out of PodSEO.</p><p>After completing the wizard, you land in the <strong>Command Center</strong> — your home base in PodSEO.</p><p>With Producer plans and above, you can track multiple podcasts. Use the sidebar menu to add more podcasts and switch between them.</p><p><img src="'+p+'" alt="Add Additional Podcasts" width="500px" style="display:block;margin:0 auto;"></p><hr><h3 id="_4-explore-key-features" tabindex="-1">4. <strong>Explore Key Features</strong> <a class="header-anchor" href="#_4-explore-key-features" aria-label="Permalink to &quot;4. **Explore Key Features**&quot;">​</a></h3><p>Once setup is complete, PodSEO opens to the sidebar navigation where all features are organized in a flat, easy-to-browse layout. Start with the Command Center and explore from there:</p><ul><li><p><strong><a href="/features/command-center.html">Command Center</a></strong> — Your dashboard home showing health signals, tasks, and insights. Start here every session.</p></li><li><p><strong><a href="/features/planner.html">Planner</a></strong> — Plan episodes, check metadata/keyword alignment, and get AI-powered optimization suggestions. Access from Command Center.</p></li><li><p><strong><a href="/features/keyword-strategy.html">Keyword Strategy</a></strong> — Define your SEO strategy with Primary, Secondary, and Monitored keywords. Found under Search Visibility.</p></li><li><p><strong><a href="/features/show-visibility.html">Show Visibility</a></strong> &amp; <strong><a href="/features/episode-visibility.html">Episode Visibility</a></strong> — See where your podcast and individual episodes rank for keywords across platforms. Found under Search Visibility.</p></li><li><p><strong><a href="/features/ai-mentions.html">AI Mentions</a></strong> — Track how often AI platforms like ChatGPT, Claude, Perplexity, and Gemini recommend your podcast. Found under AI Visibility.</p></li><li><p><strong><a href="/features/competitive-analysis.html">Competitive Analysis</a></strong> — Compare your podcast with competitors. Found under Competition.</p></li><li><p><strong><a href="/features/lucia-ai-assistant.html">LUCIA AI Chat</a></strong> — Chat with your personal SEO expert. Access via Chat in the sidebar.</p></li></ul><hr><h3 id="_5-need-help" tabindex="-1">5. <strong>Need Help?</strong> <a class="header-anchor" href="#_5-need-help" aria-label="Permalink to &quot;5. **Need Help?**&quot;">​</a></h3><ul><li><p>Browse our Help Center for tutorials and FAQs, including our <a href="/getting-started/workflow.html">detailed keyword workflow guide</a>.</p></li><li><p>Learn more about <a href="/getting-started/visibility-score-explained.html">how the Visibility Score works</a>.</p></li><li><p>Contact support via <a href="https://podseo.com/settings/contact" target="_blank" rel="noreferrer">Account Settings &gt; Contact</a>.</p></li></ul><hr><p>Start optimizing your podcast&#39;s SEO today with Podseo. For detailed guides and advanced tips, check out our comprehensive feature documentation and academy resources.</p>',34)])])}const _=t(c,[["render",u]]);export{w as __pageData,_ as default};
